import { test, expect } from '@playwright/test';

test.describe('Search Results Sorting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should sort search results by relevance, price, or date', async ({ page }) => {
    // Set up initial search state
    const searchInput = page.getByLabel('Search');
    await searchInput.fill('laptop');

    // Click the sort button for relevance
    const sortRelevanceButton = page.getByRole('button', { name: /sort by relevance/i });
    await sortRelevanceButton.click();

    // Verify results are sorted by relevance
    const resultItems = page.locator('[data-testid="search-result-item"]');
    const firstItem = await resultItems.first();
    await expect(firstItem).toContainText('Laptop Model A - Best Seller');
    const secondItem = await resultItems.nth(1);
    await expect(secondItem).toContainText('Laptop Model B - Highly Rated');

    // Click the sort button for price
    const sortPriceButton = page.getByRole('button', { name: /sort by price/i });
    await sortPriceButton.click();

    // Verify results are sorted by price
    const thirdItem = await resultItems.nth(2);
    await expect(thirdItem).toContainText('Laptop Model C - Budget');
    const fourthItem = await resultItems.nth(3);
    await expect(fourthItem).toContainText('Laptop Model A - Best Seller');

    // Click the sort button for date
    const sortDateButton = page.getByRole('button', { name: /sort by date/i });
    await sortDateButton.click();

    // Verify results are sorted by date
    const fifthItem = await resultItems.nth(4);
    await expect(fifthItem).toContainText('Laptop Model D - New Release');
    const sixthItem = await resultItems.nth(5);
    await expect(sixthItem).toContainText('Laptop Model A - Best Seller');
  });

  test('should handle empty search results gracefully', async ({ page }) => {
    // Set up initial search state with empty results
    const searchInput = page.getByLabel('Search');
    await searchInput.fill('nonexistent product');

    // Click the sort button for relevance
    const sortRelevanceButton = page.getByRole('button', { name: /sort by relevance/i });
    await sortRelevanceButton.click();

    // Verify no results are displayed
    const resultItems = page.locator('[data-testid="search-result-item"]');
    const count = await resultItems.count();
    expect(count).toBe(0);

    // Verify no error message is displayed
    const errorMessage = page.getByText(/no results found/i);
    await expect(errorMessage).toBeVisible();

    // Verify the sort button is still available
    await expect(sortRelevanceButton).toBeVisible();
  });
});
